 const save=async(e:any)=>{e.preventDefault();setSaving(true);try{const id=f.id.trim().toUpperCase().replace(/\s+/g,"-");if(!id||!f.name.trim())throw new Error("Location code and name are required.");if(LOCATIONS.some(x=>x.id===id))throw new Error("That location code is already reserved.");await setDoc(doc(db,"locations",id),{name:f.name.trim(),active:true,createdAt:serverTimestamp(),updatedAt:serverTimestamp()});onClose()}catch(err:any){alert(err.message)}finally{setSaving(false)}};
